    self,

def _takeover_approval_message(
    dispatch_id: str, adapter_id: str
) -> str:
    """接管审批单 message 必须逐字一致的紧凑 JSON（无空格、键序固定为
    dispatch_id,adapter_id）。"""
    return json.dumps(
        {
